pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"system.cost.openrouter","description":"LIVE SPEND from OpenRouter itself (operator 2026-07-10: \"the cost center should pull from openrouter the value spent\") — GET /credits (account total usage + credits) + GET /key (this key's lifetime usage). The headline truth that can never miss untracked calls; local ai_calls rows stay the per-call breakdown. Read-only, free.","owner_agent":"system","steps_json":"[{\"skill\":\"openrouter-spend\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.cost.settings","description":"EPIC-FE-BE-INTEGRATION: get/set the operator-managed cost cap. Read unrestricted; write is god-mode at BE layer. Powers FE Settings/Cost.","owner_agent":"system","steps_json":"[{\"skill\":\"cost-settings\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.cost.aggregate","description":"EPIC-FE-BE-INTEGRATION: cost rollups for the FE Cost Center. One skill, four view modes (today | sub_skill_matrix | provider_mix | agent_mix). Caller passes both view and window_hours. BE controllers dispatch this directly with the view set per route.","owner_agent":"system","steps_json":"[{\"skill\":\"cost-aggregate\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.cost.today","description":"EPIC-FE-BE-INTEGRATION: today's spend vs cap + top-3 prompts by cost. View=today wrapper around system.cost.aggregate.","owner_agent":"system","steps_json":"[{\"skill\":\"cost-aggregate\",\"input\":{\"view\":\"today\"},\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.cost.sub-skill-matrix","description":"EPIC-FE-BE-INTEGRATION: per-prompt cost matrix (actual vs Opus baseline, cached %). View=sub_skill_matrix.","owner_agent":"system","steps_json":"[{\"skill\":\"cost-aggregate\",\"input\":{\"view\":\"sub_skill_matrix\"},\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.cost.provider-mix","description":"EPIC-FE-BE-INTEGRATION: provider donut data (anthropic/openai/groq/local × share × cost). View=provider_mix.","owner_agent":"system","steps_json":"[{\"skill\":\"cost-aggregate\",\"input\":{\"view\":\"provider_mix\"},\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"system.cost.agent-mix","description":"EPIC-FE-BE-INTEGRATION: agent bar data (pl/tl/dev/qa/man/system × calls × cost). View=agent_mix.","owner_agent":"system","steps_json":"[{\"skill\":\"cost-aggregate\",\"input\":{\"view\":\"agent_mix\"},\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 7, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
